select * replace (
  case ticker when 'PLD' then 'Prologis' when 'EGP' then 'EastGroup Properties' when 'FR' then 'First Industrial Realty Trust' when 'STAG' then 'STAG Industrial' when 'TRNO' then 'Terreno Realty' when 'REXR' then 'Rexford Industrial Realty' when 'SPG' then 'Simon Property Group' when 'KIM' then 'Kimco Realty' when 'REG' then 'Regency Centers' when 'FRT' then 'Federal Realty Investment Trust' when 'BRX' then 'Brixmor Property Group' when 'NNN' then 'NNN REIT' when 'O' then 'Realty Income' when 'ADC' then 'Agree Realty' when 'BXP' then 'BXP' when 'VNO' then 'Vornado Realty Trust' when 'KRC' then 'Kilroy Realty' when 'HIW' then 'Highwoods Properties' when 'CUZ' then 'Cousins Properties' when 'DEI' then 'Douglas Emmett' when 'SLG' then 'SL Green Realty' when 'ESS' then 'Essex Property Trust' when 'UDR' then 'UDR' when 'MAA' then 'Mid-America Apartment Communities' when 'CPT' then 'Camden Property Trust' when 'INVH' then 'Invitation Homes' when 'AMH' then 'American Homes 4 Rent' when 'WELL' then 'Welltower' when 'VTR' then 'Ventas' when 'DOC' then 'Healthpeak Properties' when 'OHI' then 'Omega Healthcare Investors' when 'EQIX' then 'Equinix' when 'DLR' then 'Digital Realty Trust' when 'AMT' then 'American Tower' when 'CCI' then 'Crown Castle' when 'PSA' then 'Public Storage' when 'EXR' then 'Extra Space Storage' when 'CUBE' then 'CubeSmart' when 'HST' then 'Host Hotels & Resorts' when 'PK' then 'Park Hotels & Resorts' when 'RHP' then 'Ryman Hospitality Properties' when 'VICI' then 'VICI Properties' when 'GLPI' then 'Gaming and Leisure Properties' when 'WPC' then 'W. P. Carey' when 'EPR' then 'EPR Properties' when 'IRM' then 'Iron Mountain' when 'LAMR' then 'Lamar Advertising' when 'SBAC' then 'SBA Communications' when 'ARE' then 'Alexandria Real Estate Equities' when 'MPT' then 'Medical Properties Trust' else company_name end as company_name
),
  case subsector when 'life_science' then 'Life Science' when 'data_center' then 'Data Center' when 'gaming_netlease' then 'Gaming & Net Lease' when 'storage' then 'Self-Storage' when 'tower' then 'Cell Towers' when 'hotel' then 'Hotels & Lodging' when 'industrial' then 'Industrial' when 'retail' then 'Retail' when 'office' then 'Office' when 'residential' then 'Residential' when 'healthcare' then 'Healthcare' when 'specialty' then 'Specialty' else subsector end as sector,
  case latest_ebitda_method when 'operating_income+da' then 'Operating income + D&A' when 'pretax+interest+da' then 'Pre-tax income + interest + D&A' when 'net_income+tax+interest+da' then 'Net income + tax + interest + D&A' when 'net_income+interest+da (tax=0)' then 'Net income + interest + D&A (no tax line)' else latest_ebitda_method end as ebitda_basis
from stress_ranking